using System.Linq; using common.resources; using wServer.realm.entities;
namespace wServer.realm.worlds.logic { class AshenFoundry:World { Enemy sun; int vents; bool done,populated; public AshenFoundry(ProtoWorld p,wServer.networking.Client c=null):base(p){DungeonAnomalyService.Attach(this,DungeonAnomalyService.Roll(DungeonCodexService.All.FirstOrDefault(x=>x.Key=="AshenFoundry"),new System.Random(Id)));} public override int EnterWorld(Entity e){var id=base.EnterWorld(e);if(e is Player&&!populated){populated=true;Spawn("Foundry Guard",2,2);Spawn("Foundry Guard",7,2);Spawn("Furnace Overseer",5,4);Spawn("Heat Vent",3,7);Spawn("Heat Vent",5,7);Spawn("Heat Vent",7,7);Spawn("The Iron Sun",5,8);}var n=e as Enemy;if(n==null)return id;DungeonAnomalyService.Apply(this,n);n.OnDeath+=(s,a)=>Dead(n);if(n.ObjectDesc.ObjectId=="The Iron Sun"){sun=n;sun.ApplyConditionEffect(ConditionEffectIndex.Invincible);}return id;}void Spawn(string n,float x,float y){var e=Entity.Resolve(Manager,n);if(e!=null){e.Move(x,y);EnterWorld(e);}}void Dead(Enemy e){if(e.ObjectDesc.ObjectId=="Heat Vent"&&++vents>=3&&sun!=null)sun.ApplyConditionEffect(ConditionEffectIndex.Invincible,0);if(e.ObjectDesc.ObjectId=="The Iron Sun"&&!done){done=true;DungeonAnomalyService.Cleanup(this);foreach(var p in Players.Values)p.SendInfo("Ashen Foundry cleared.");}}} }
